import{_ as p,h as c,i as a,c as s,v as t,p as i,x as r,m as l,e as n,S}from"./chunks/framework.Dvtg8yj2.js";const d=JSON.parse('{"title":"Spectrum-6 共封装光学以太网","description":"","frontmatter":{"title":"Spectrum-6 共封装光学以太网","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spectrum-6-cpo.md","filePath":"llm/spectrum-6-cpo.md","lastUpdated":1788454257000}'),u={name:"llm/spectrum-6-cpo.md"};function A(m,e,C,E,P,h){const o=c("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="spectrum-6-共封装光学以太网" tabindex="-1">Spectrum-6 共封装光学以太网 <a class="header-anchor" href="#spectrum-6-共封装光学以太网" aria-label="Permalink to &quot;Spectrum-6 共封装光学以太网&quot;">​</a></h1><div class="epigraph"><p>可插拔光模块把光电转换留在笼子里；共封装光学把光引擎贴到交换机 ASIC 旁边，少一截电接口，也少一截工厂里最爱坏的零件。</p><footer>—— NVIDIA 对 Spectrum-X Ethernet Photonics 的公开描述：光引擎与交换机芯片同一封装，外部激光源供光</footer></div><p><a href="/llm/connectx-9-spectrum-x">ConnectX-9</a> 是 scale-out 的端点。本篇写对端的交换机：Spectrum-6。NVIDIA 公开把它写成 102.4 Tb/s 级以太网交换，相对上一代系统容量约 2 倍，并作为 Vera Rubin 平台的六芯片之一，与 ConnectX-9 组成下一代 Spectrum-X。形态上同时支持可插拔光学与共封装光学（CPO）；CPO 产品线被称作 Spectrum-X Ethernet Photonics。本篇只讨论已经写进官方博客与交换机数据表的结构，不把合作伙伴新闻稿里的工艺节点当成 NVIDIA 数据手册，也不编造未公开的 BER 曲线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AI 工厂的交换机首先是功耗与故障零件的问题，其次才是「再多几个 800G 端口」。传统可插拔模块（QSFP-DD / OSFP）每端口一套激光、一套 DSP、一套笼子。十万 GPU 的 Clos 里，光模块数量与交换机端口数同量级；模块的电接口、插拔接触和激光老化，是现场最常见的网络故障源之一。模块自己也吃电：在交换机 ASIC 已经很热的前提下，端口光电转换往往成为机柜功耗里「不算算力、却按端口线性涨」的一项。</p><p>以太网还要面对 AI 流量：集合通信的同步突发、需要自适应路由与共享缓存，而不是数据中心南北向的大象流加老鼠流。Spectrum-X 已经在协议与芯片行为上改过一轮；Spectrum-6 要把端口速率、交换容量和光学形态再抬一档，否则 Rubin 机柜的向外带宽会在叶子层被削掉。问题是：CPO 用封装换掉可插拔之后，运维模型怎么变——现场还能不能像换光模块一样换端口。</p><h3 id="cpo-换掉的是笼子-不是以太网" tabindex="-1">CPO 换掉的是笼子，不是以太网 <a class="header-anchor" href="#cpo-换掉的是笼子-不是以太网" aria-label="Permalink to &quot;CPO 换掉的是笼子，不是以太网&quot;">​</a></h3><p>共封装光学把硅光引擎放到与交换机 ASIC 同一封装上，光纤进到封装附近，光电转换紧贴交换芯片。NVIDIA 公开写：内部光布线把光纤引到封装，硅光引擎在 ASIC 旁边把光转电；外部激光源（ELS）持续供光，以降低封装上的热并改善规模下的可靠性。以太网协议、RoCE、自适应路由仍在；变的是物理层从「每端口一个可插拔」变成「封装级光引擎 + 集中激光」。不要把 CPO 理解成一种新的集合通信，也不要理解成 InfiniBand 专用——同一套叙事在 Spectrum-X（以太）与 Quantum-X Photonics（IB）上分别出现。</p><p><span class="marginnote">NVIDIA 给 Photonics 交换机写过相对可插拔约 5 倍能效、约 10 倍故障间隔（MTBI / 可靠性）的平台数字。那是厂商对照，依赖具体模块与拓扑。本篇用来理解「光学形态是一等设计约束」，不把 5 倍抄进自己的 PUE 表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按官方系统形态选型。公开技术博客给出两款液冷 CPO 机箱，都基于 Spectrum-6 ASIC：</p><ul><li>SN6810：102.4 Tb/s，128 个 800 Gb/s 端口（单 ASIC）。</li><li>SN6800：409.6 Tb/s，512 个 800 Gb/s 端口（四 ASIC 级系统，带集成光纤整理）。</li></ul><p>数据表还强调：每 ASIC 聚合带宽大于 102.4 Tb/s、建立在 200G SerDes 上、每端口 800 Gb/s，以及面向 Spectrum-X 的自适应路由、拥塞控制、性能隔离、全共享单体包缓存、硬件多平面。可插拔形态同样存在（公开材料里的 SN6600 一类：128×800G，风冷/液冷），给尚未准备 CPO 运维的机房一条过渡路径。Spectrum-6 系统支持液冷，以便和 Rubin 机柜的全液冷工厂对齐。</p>',13)),(a(),i(S,null,{default:r(()=>[n(o,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TB%0A%20%20ASIC%5B%22Spectrum-6%20ASIC%22%5D%0A%20%20OE%5B%22%E5%B0%81%E8%A3%85%E4%B8%8A%E7%9A%84%E7%A1%85%E5%85%89%E5%BC%95%E6%93%8E%22%5D%0A%20%20ELS%5B%22%E5%A4%96%E9%83%A8%E6%BF%80%E5%85%89%E6%BA%90%20ELS%22%5D%0A%20%20FIB%5B%22%E5%85%89%E7%BA%A4%E5%88%B0%E6%9C%BA%E6%9F%9C%22%5D%0A%20%20ASIC%20---%20OE%0A%20%20ELS%20--%3E%20OE%0A%20%20OE%20--%3E%20FIB%0A%20%20FIB%20--%3E%20CX%5B%22ConnectX-9%20%E7%AB%AF%E7%82%B9%22%5D%0A%20%20ASIC%20--%3E%20FEAT%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E8%B7%AF%E7%94%B1%20%2F%20%E5%85%B1%E4%BA%AB%E7%BC%93%E5%AD%98%20%2F%20%E5%A4%9A%E5%B9%B3%E9%9D%A2%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="拓扑仍按-clos-与多平面来画" tabindex="-1">拓扑仍按 Clos 与多平面来画 <a class="header-anchor" href="#拓扑仍按-clos-与多平面来画" aria-label="Permalink to &quot;拓扑仍按 Clos 与多平面来画&quot;">​</a></h3><p>CPO 不取消叶子与脊。它改变的是每台交换机的端口密度、功耗和现场可换零件。硬件多平面拓扑被 NVIDIA 写成可减少交换机台数约 1.7 倍；这与光学形态正交——可插拔 Spectrum-X 也能多平面，CPO 只是让高密度 800G 更吃得消。规划时先钉：端点是 ConnectX-9、交换是 Spectrum-6、协议是 Spectrum-X 的自适应路由与拥塞控制，再决定这一跳用 CPO 还是可插拔。开放网络操作系统与可选 RDMA 传输模型是官方强调的「垂直整合、水平开放」：硅和系统成套，以太协议仍标准。</p><p>遥测方面，数据表列出硬件加速的高频遥测、包级事件诊断、NVUE / SDK / SONiC、OTLP / gNMI 等开放接口。AI 作业的「哪一条流在哪一跳排队」要靠这些，而不是靠 ping。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可插拔方案的功耗与故障，很大一部分发生在 ASIC 之外的电接口上：重定时、DSP、笼子损耗。CPO 把这段缩短，光在更靠近交换逻辑的地方进出，SerDes 按 200G 档设计。ELS 把激光从热封装上拿开，是可靠性策略：激光老化与换件可以发生在模块化的光源上，而不必把整颗交换 ASIC 当成光学现场备件。NVIDIA 还把液冷写进交换机，使网络设备与计算托盘走同一套温水回路，而不是在全液冷机房里留一排风冷叶子。</p><p>对 LLM 作业，交换机的「智能」仍然是 Spectrum-X 那一套：路径喷洒、快速绕开故障、精确恢复丢包。CPO 提高的是把这些行为撑到 800G × 上百端口时的电与热可行性。集合通信的有效带宽取决于拥塞控制是否在端到端生效；光学再近，也救不了 PFC 配错或哈希钉死。官方平台数字——相对 OTS 以太网约 1.6 倍 AI 网络性能、十万 GPU 以上约 95% 网络效率——描述的是整套 Spectrum-X，不是单独一块硅光。</p><p><span class="marginnote">合作伙伴公开材料里出现过 Spectrum-6 ASIC 的工艺节点叙述。NVIDIA 自己的交换机数据表与博客强调的是 102.4 Tb/s、200G SerDes 与 CPO 结构。工艺节点以 NVIDIA 或晶圆厂的正式披露为准，本文不把第三方新闻稿写成已核验的工艺表。</span></p><h3 id="运维-现场换的是什么" tabindex="-1">运维：现场换的是什么 <a class="header-anchor" href="#运维-现场换的是什么" aria-label="Permalink to &quot;运维：现场换的是什么&quot;">​</a></h3><p>可插拔时代，坏端口往往换模块。CPO 时代，端口光引擎在封装上，现场可换单元变成光纤跳线、ELS、整台交换机或托盘。这要求备件模型从「一盒光模块」改成「交换机与激光源」。官方强调技术员可维护性与更快上电，但没有把 CPO 写成可以像 SFP 一样热插每一路光引擎。写 runbook 时不要假设「CPO = 还是换模块」。液冷交换机的泄漏与 UQD 接头，属于与计算托盘相同的设施纪律。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在普通 25G 叶子上「开启 Spectrum-X 软件」来假装有 CPO。不要把 SN6800 的 409.6 Tb/s 理解成单 ASIC 容量——公开写法是四 ASIC 级系统。不要用营销能效倍数替代机房的实测 PUE。Quantum-X Photonics 的 IB CPO 与 Spectrum-X 的以太 CPO 是两条产品线，端口语义与软件栈不同，不能混接当成同一 fabric。</p><p>CPO 提高封装与供应链的耦合：交换机 ASIC 与光引擎一起验证。好处是整机效率；代价是迭代周期与故障替换粒度变大。若机房短期内必须沿用大量可插拔备件，SN6600 一类可插拔 Spectrum-6 是官方留下的口子。</p><p><span class="marginnote">出处：NVIDIA Spectrum-6 官方博客、SN6000 / Spectrum-X Ethernet Photonics 数据表、Scaling AI Factories with CPO 技术博文中的 SN6810 / SN6800 端口表，以及 Vera Rubin POD 文中对 Spectrum-6 SPX 机柜的描述。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Spectrum-6 是下一代 Spectrum-X 的交换机 ASIC，公开容量为每 ASIC 102.4 Tb/s 级、200G SerDes、800 Gb/s 端口。</li><li>CPO 把硅光引擎与 ASIC 共封装，ELS 在封装外供光，目标是功耗、可靠性与可维护性，而不是新的集体通信算法。</li><li>公开 CPO 系统包括 SN6810（128×800G）与 SN6800（512×800G）；可插拔形态仍然存在。</li><li>自适应路由、共享缓存与多平面属于 Spectrum-X 行为，与光学形态正交。</li><li>运维备件从可插拔模块转向光纤、ELS 与整机；不要按 SFP 热插模型去写 CPO。</li><li>出处：NVIDIA Spectrum-6 / Photonics 公开文档。</li></ul>',15))])}const B=p(u,[["render",A]]);export{d as __pageData,B as default};
